import { Point } from './point.js';
import { Strings } from '../lib/strings.js';
import { Entity } from './entity.js';
import { Input, PromptOptions } from '../lib/inputManager.js';
import { Logging } from '../lib/logging.js';
import { DXFFile } from '../lib/dxf/dxfFile.js';
import { BoundingBox } from '../lib/boundingBox.js';
import { Property } from '../properties/property.js';
import { Utils } from '../lib/utils.js';

import { DesignCore } from '../designCore.js';
import { AddState, RemoveState } from '../lib/stateManager.js';
import { SnapPoint } from '../lib/snapping.js';

/**
 * Circle Entity Class
 * @extends Entity
 */
export class Circle extends Entity {
  static type = 'Circle';

  /**
   * Create a Circle Entity
   * @param {Array} data
   */
  constructor(data) {
    super(data);

    // add radius property with getter and setter
    // needs to be enumerable to appear in the object props
    Object.defineProperty(this, 'radius', {
      get: this.getRadius,
      set: this.setRadius,
      enumerable: true,
    });

    if (data) {
      if (data.hasOwnProperty('radius') || data.hasOwnProperty('40')) {
        // DXF Groupcode 40 - Radius
        this.setRadius(Property.loadValue([data.radius, data[40]], 0));
      }
    }
  }

  /**
   * Register the command
   * @return {Object}
   * command = name of the command
   * shortcut = shortcut for the command
   * type = type to group command in toolbars (omitted if not shown)
   */
  static register() {
    const command = { command: 'Circle', shortcut: 'C', type: 'Entity' };
    return command;
  }

  /**
   * Execute method
   * executes the workflow, requesting input required to create an entity
   */
  async execute() {
    try {
      const op = new PromptOptions(Strings.Input.CENTER, [Input.Type.POINT]);
      const pt1 = await DesignCore.Scene.inputManager.requestInput(op);
      if (pt1 === undefined) return;
      this.points.push(pt1);

      const op2 = new PromptOptions(Strings.Input.RADIUS, [Input.Type.POINT, Input.Type.NUMBER], ['Diameter']);

      while (true) {
        const pt2 = await DesignCore.Scene.inputManager.requestInput(op2);
        if (pt2 === undefined) return;

        if (Input.getType(pt2) === Input.Type.POINT) {
          if (pt1.distance(pt2) <= 0) {
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.NONZERO}`);
            continue;
          }
          this.points.push(pt2);
          break;
        } else if (Input.getType(pt2) === Input.Type.NUMBER) {
          if (pt2 <= 0) {
            DesignCore.Core.notify(`${this.type} - ${Strings.Error.NONZERO}`);
            continue;
          }
          this.setRadius(pt2);
          break;
        } else if (Input.getType(pt2) === Input.Type.STRING && pt2 === 'Diameter') {
          const op3 = new PromptOptions(Strings.Input.DIAMETER, [Input.Type.NUMBER]);
          while (true) {
            const diameter = await DesignCore.Scene.inputManager.requestInput(op3);
            if (diameter === undefined) return;
            if (diameter <= 0) {
              DesignCore.Core.notify(`${this.type} - ${Strings.Error.NONZERO}`);
              continue;
            }
            this.setRadius(diameter / 2);
            break;
          }
          break;
        }
      }

      DesignCore.Scene.inputManager.executeCommand(this);
    } catch (err) {
      Logging.instance.error(`${this.type} - ${err}`);
    }
  }

  /**
   * Preview the entity during creation
   */
  preview() {
    if (this.points.length >= 1) {
      const mousePoint = DesignCore.Mouse.pointOnScene();
      const points = [this.points.at(-1), mousePoint];
      DesignCore.Scene.tempEntities.create(this.type, { points: points });
    }
  }

  /**
   * Get Circle radius
   * @return {number} - circle radius
   */
  getRadius() {
    return this.points[0].distance(this.points[1]);
  }

  /**
   * Set Circle radius
   * @param {number} rad
   */
  setRadius(rad) {
    this.points[1] = this.points[0].project(0, rad);
  }

  /**
   * Draw the entity
   * @param {Object} ctx - context
   * @param {number} scale
   */
  draw(ctx, scale) {
    ctx.arc(this.points[0].x, this.points[0].y, this.radius, 0, 6.283);
    ctx.stroke();
  }

  /**
   * Write the entity to file in the dxf format
   * @param {DXFFile} file
   */
  dxf(file) {
    file.writeGroupCode('0', 'CIRCLE');
    file.writeGroupCode('5', this.handle, DXFFile.Version.R2000); // Handle
    file.writeGroupCode('100', 'AcDbEntity', DXFFile.Version.R2000);
    file.writeGroupCode('100', 'AcDbCircle', DXFFile.Version.R2000);
    file.writeGroupCode('8', this.layer);
    file.writeGroupCode('6', this.lineType);
    this.writeDxfColour(file);
    file.writeGroupCode('10', this.points[0].x);
    file.writeGroupCode('20', this.points[0].y);
    file.writeGroupCode('30', '0.0');
    file.writeGroupCode('39', this.lineWidth);
    file.writeGroupCode('40', this.radius);
  }

  /**
   * Return a list of points representing a polyline version of this entity
   * @return {Array}
   */
  toPolylinePoints() {
    const startPoint = this.points[0].project(0, this.radius);
    startPoint.bulge = 1;
    const endPoint = this.points[0].project(0, -this.radius);
    endPoint.bulge = 1;
    const closurePoint = this.points[0].project(0, this.radius);
    return [startPoint, endPoint, closurePoint];
  }

  /**
   * Set entity points from a polyline point representation
   * @param {Array} points
   */
  fromPolylinePoints(points) {
    const center = points[0].bulgeCentrePoint(points[1]);
    const radius = center.distance(points[0]);
    this.points = [center, center.project(0, radius)];
  }

  /**
   * Trim the entity
   * @param {Array} intersections
   * @return {Array} - array of state changes
   */
  trim(intersections) {
    // array to hold state changes
    const stateChanges = [];

    if (intersections?.length === 0 || !intersections) {
      return stateChanges;
    }

    const direction = 1; // Circle is always CCW for trimming purposes

    // get the mouse position
    const mousePosition = DesignCore.Mouse.pointOnScene();
    // get the point on the arc closest to the mouse
    const pointOnCircle = mousePosition.closestPointOnArc(this.points[1], this.points[1], this.points[0]);
    // sort intersection points
    Utils.sortPointsOnArc(intersections, this.points[0], this.points[0], this.points[0], direction);
    // Repeat the first point to close the circle
    const testPoints = [...intersections, intersections.at(0)]; // Closing the circle

    // Test if mouse position is between two intersection points
    if (testPoints.length > 1) {
      for (let i = 0; i < testPoints.length - 1; i++) {
        const startPoint = testPoints[i];
        const endPoint = testPoints[i + 1];

        // check if the mouse is between startPoint and endPoint
        if (pointOnCircle.isOnArc(startPoint, endPoint, this.points[0], direction)) {
          // create a new arc entity
          const arc = DesignCore.CommandManager.createNew('Arc', this);
          arc.handle = undefined;
          // flip direction
          arc.direction = direction * -1;
          arc.points = [this.points[0], startPoint, endPoint];
          const addState = new AddState(arc);
          stateChanges.push(addState);

          // Remove the existing arc
          if (stateChanges.length > 0) {
            const removeState = new RemoveState(this);
            stateChanges.push(removeState);
            return stateChanges;
          }
        }
      }
    }

    return stateChanges;
  }

  /**
   * Get snap points
   * @param {Point} mousePoint
   * @param {number} delta
   * @return {Array} - array of snap points
   */
  snaps(mousePoint, delta) {
    const snaps = [];

    const centre = this.points[0]; // circle centre point

    snaps.push(new SnapPoint(centre, SnapPoint.Type.CENTRE));

    snaps.push(
        new SnapPoint(new Point(centre.x + this.radius, centre.y), SnapPoint.Type.QUADRANT), // 0°
        new SnapPoint(new Point(centre.x, centre.y + this.radius), SnapPoint.Type.QUADRANT), // 90°
        new SnapPoint(new Point(centre.x - this.radius, centre.y), SnapPoint.Type.QUADRANT), // 180°
        new SnapPoint(new Point(centre.x, centre.y - this.radius), SnapPoint.Type.QUADRANT), // 270°
    );

    if (mousePoint) {
      const [nearestPoint, nearestDistance] = this.closestPoint(mousePoint);
      // Crude way to snap to the closest point on the circle
      if (nearestDistance < delta / 10) {
        snaps.push(new SnapPoint(nearestPoint, SnapPoint.Type.NEAREST));
      }
    }

    const fromPoint = DesignCore.Scene.inputManager.inputPoint; // last confirmed input point (line start)
    if (fromPoint !== null) {
      const distanceToCenter = centre.distance(fromPoint); // distance from the input point to the circle centre
      const angleFromCentreToInput = centre.angle(fromPoint); // angle from centre toward fromPoint

      // Tangent: only possible when fromPoint is outside the circle radius
      if (distanceToCenter > this.radius) {
        const tangentHalfAngle = Math.acos(this.radius / distanceToCenter); // half-angle between the two tangent directions

        snaps.push(new SnapPoint(centre.project(angleFromCentreToInput + tangentHalfAngle, this.radius), SnapPoint.Type.TANGENT));
        snaps.push(new SnapPoint(centre.project(angleFromCentreToInput - tangentHalfAngle, this.radius), SnapPoint.Type.TANGENT));
      }

      // Perpendicular: point on the circle that lies on the line from fromPoint through the centre
      if (distanceToCenter > 0) {
        snaps.push(new SnapPoint(centre.project(angleFromCentreToInput, this.radius), SnapPoint.Type.PERPENDICULAR));
      }
    }

    return snaps;
  }

  /**
   * Get closest point on entity
   * @param {Point} P
   * @return {Array} - [Point, distance]
   */
  closestPoint(P) {
    // find the closest point on the circle
    const closest = P.closestPointOnArc(this.points[1], this.points[1], this.points[0]);
    const distance = closest.distance(P);

    return [closest, distance];
  }

  /**
   * Return boundingbox for entity
   * @return {BoundingBox}
   */
  boundingBox() {
    const xmin = this.points[0].x - this.radius;
    const xmax = this.points[0].x + this.radius;
    const ymin = this.points[0].y - this.radius;
    const ymax = this.points[0].y + this.radius;

    const topLeft = new Point(xmin, ymax);
    const bottomRight = new Point(xmax, ymin);

    return new BoundingBox(topLeft, bottomRight);
  }
}
