import { DesignCore } from '../designCore.js';

/** Settings Class */
export class Settings {
  /** Create Setting */
  constructor() {
    this.canvasbackgroundcolour = { r: 30, g: 30, b: 30 };
    this.gridcolour = { r: 119, g: 118, b: 123 };
    this.selecteditemscolour = { r: 0, g: 255, b: 0 };
    this.snaptrackingcolour = { r: 55, g: 180, b: 75 };
    // selectionWindow and crossingWindow colours
    this.selectionWindow = { r: 0, g: 255, b: 0 };
    this.crossingWindow = { r: 0, g: 0, b: 255 };
    // fontSettings
    this.font = 'Arial';
    this.fontupsidedown = false;
    this.fontbackwards = false;
    // snapSettings
    this.endsnap = true;
    this.midsnap = true;
    this.centresnap = true;
    this.nearestsnap = false;
    this.quadrantsnap = false;
    this.tangentsnap = false;
    this.nodesnap = false;
    this.perpendicularsnap = false;
    // trackingSettings
    this.polar = true;
    this.polarangle = 45;
    this.ortho = false;
    // gridSettings
    this.drawgrid = true;
  }

  /**
   * Sets the value of the setting
   * @param {string} setting
   * @param {any} value
   */
  setSetting(setting, value) {
    // TODO: Check setting is valid
    this[setting] = value;

    // polar and ortho are mutually exclusive — enabling one disables the other
    if (value === true) {
      if (setting === 'polar') this.ortho = false;
      else if (setting === 'ortho') this.polar = false;
    }

    if (DesignCore.instance) {
      DesignCore.Canvas.requestPaint();
    }
  }

  /**
   * Returns the value of the setting
   * @param {string} setting
   * @return {string}
   */
  getSetting(setting) {
    // TODO: Validate setting exists
    return this[setting];
  }
}
